const resyncMCPServerRemoteSessionIssuers = `-- name: ResyncMCPServerRemoteSessionIssuers :execrows
WITH resolved AS (
    SELECT input.user_session_issuer_id,
           CASE WHEN count(DISTINCT i.id) = 1
                THEN (array_agg(DISTINCT i.id))[1]
           END AS remote_session_issuer_id
    FROM unnest($3::uuid[]) AS input(user_session_issuer_id)
    JOIN user_session_issuers AS usi
      ON usi.id = input.user_session_issuer_id
    LEFT JOIN projects AS usi_project
           ON usi_project.id = usi.project_id
    LEFT JOIN remote_session_client_user_session_issuers AS link
           ON link.user_session_issuer_id = input.user_session_issuer_id
    LEFT JOIN remote_session_clients AS c
           ON c.id = link.remote_session_client_id
          AND c.deleted IS FALSE
          AND (c.project_id = usi.project_id
               OR (c.project_id IS NULL
                   AND c.organization_id = COALESCE(usi_project.organization_id, usi.organization_id)))
    LEFT JOIN remote_session_issuers AS i
           ON i.id = c.remote_session_issuer_id
          AND i.deleted IS FALSE
    GROUP BY input.user_session_issuer_id
)
UPDATE mcp_servers AS s
SET remote_session_issuer_id = resolved.remote_session_issuer_id,
    updated_at = clock_timestamp()
FROM resolved
JOIN user_session_issuers AS usi
  ON usi.id = resolved.user_session_issuer_id
WHERE s.user_session_issuer_id = resolved.user_session_issuer_id
  -- Axis 1: the caller's scope. UPDATE ... FROM cannot reference the target
  -- table in a FROM-item join condition, hence EXISTS rather than a join.
  AND EXISTS (SELECT 1
              FROM projects AS caller_project
              WHERE caller_project.id = s.project_id
                AND caller_project.organization_id = $1::text)
  AND ($2::uuid IS NULL
       OR s.project_id = $2::uuid)
  -- Axis 2: the issuer's own tenancy must cover the server it stamps.
  AND (s.project_id = usi.project_id
       OR (usi.project_id IS NULL
           AND usi.organization_id IS NOT NULL
           AND EXISTS (SELECT 1
                       FROM projects AS issuer_project
                       WHERE issuer_project.id = s.project_id
                         AND issuer_project.organization_id = usi.organization_id)))
  AND s.deleted IS FALSE
  AND s.remote_session_issuer_id IS DISTINCT FROM resolved.remote_session_issuer_id
`

type ResyncMCPServerRemoteSessionIssuersParams struct {
	OrganizationID       string
	ProjectID            uuid.NullUUID
	UserSessionIssuerIds []uuid.UUID
}

// Recomputes mcp_servers.remote_session_issuer_id from the live client
// bindings on each named user session issuer, so the column tracks the
// authorization server an MCP server's upstream actually authenticates
// against without any caller having to derive it.
//
// Exactly one distinct remote session issuer across the bound clients stamps
// it; none or several leave it NULL. Several is representable — AIS-137
// dropped the one-client-per-user-session-issuer index, so a user session
// issuer may bind clients across distinct remote issuers — and a scalar column
// cannot name which, so it names none and the readers fail closed.
//
// Clients are only ever soft-deleted, so `c.deleted IS FALSE` is the removal
// signal here. The column's own FK is ON DELETE SET NULL, but no application
// code hard-deletes a remote session issuer; the one hard delete in the tree
// is the demo seed's DELETE FROM projects, whose cascade takes the mcp_servers
// rows with it. So SET NULL never has a surviving row to fix up and cannot be
// relied on to clear a stale value. `i.deleted IS FALSE` is redundant today — every
// issuer delete is blocked while any live client references it
// (CountRemoteSessionClientsByIssuerID), under the same advisory lock the
// client writers take — but it keeps this derivation identical to
// ListRemoteSessionClientsForUserSessionIssuer, the resolver that actually
// picks the credential at serve time. The column must never name an issuer
// that resolver would refuse, so it filters on the same terms rather than
// inheriting the guarantee from a check in another file.
//
// Tenancy is enforced on three independent axes, because the ids in
// @user_session_issuer_ids are not themselves proof of anything: they are read
// back from join tables that carry no tenancy column, so a bug upstream could
// put any id in the array.
//
//  1. The CALLER's scope. @organization_id is required and every written
//     server must sit in a project of that organization; project_id narrows
//     further when the caller has one. Callers that legitimately span
//     projects (the org-admin client delete, both issuer migrations) pass
//     only the organization and are correct; no caller may pass neither.
//  2. Which servers the issuer may write — the issuer must own the server's
//     project directly, or (org-tier issuer, project_id NULL) own the
//     organization that project belongs to. Without the second arm an
//     org-tier issuer matches nothing, which fails closed for stamping but
//     OPEN for clearing: a value written while the issuer was project-scoped
//     could never be cleared again.
//  3. Which clients count — a client is only visible to an issuer in its own
//     tenant, mirroring ListRemoteSessionClientsForUserSessionIssuer. Without
//     this the join table alone decides, and a binding to another project's
//     client stamps that project's issuer onto this project's server.
//
// Axis 2 alone was the original design and is not sufficient: it constrains
// the relationship between a server and the issuer it already names, which
// every writer establishes in one project in one transaction, so it is
// vacuous today and silently becomes a no-op the moment an org-tier issuer
// appears. It says nothing about who asked.
//
// PRECONDITION: the caller holds
// LockUserSessionIssuerForRemoteIssuerDerivation for every id in the array,
// taken before any row lock in the transaction. Without it two writers on one
// user session issuer compute from snapshots missing each other's binding and
// the last commit wins with a value that was never true.
func (q *Queries) ResyncMCPServerRemoteSessionIssuers(ctx context.Context, arg ResyncMCPServerRemoteSessionIssuersParams) (int64, error) {
	result, err := q.db.Exec(ctx, resyncMCPServerRemoteSessionIssuers, arg.OrganizationID, arg.ProjectID, arg.UserSessionIssuerIds)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const setMCPServerToolMetadata = `-- name: SetMCPServerToolMetadata :many
WITH input AS (
    SELECT
        elem->>'tool_name' AS tool_name,
        elem->>'title' AS title,
        (elem->>'read_only_hint')::boolean AS read_only_hint,
        (elem->>'destructive_hint')::boolean AS destructive_hint,
        (elem->>'idempotent_hint')::boolean AS idempotent_hint,
        (elem->>'open_world_hint')::boolean AS open_world_hint
    FROM jsonb_array_elements($1::jsonb) AS elem
),
upserted AS (
    INSERT INTO mcp_server_tool_metadata (
        project_id,
        mcp_server_id,
        tool_name,
        title,
        read_only_hint,
        destructive_hint,
        idempotent_hint,
        open_world_hint
    )
    SELECT
        $2,
        $3,
        input.tool_name,
        input.title,
        input.read_only_hint,
        input.destructive_hint,
        input.idempotent_hint,
        input.open_world_hint
    FROM input
    ON CONFLICT (mcp_server_id, tool_name) WHERE deleted IS FALSE
    DO UPDATE SET
        title = EXCLUDED.title,
        read_only_hint = EXCLUDED.read_only_hint,
        destructive_hint = EXCLUDED.destructive_hint,
        idempotent_hint = EXCLUDED.idempotent_hint,
        open_world_hint = EXCLUDED.open_world_hint,
        updated_at = clock_timestamp()
    WHERE mcp_server_tool_metadata.project_id = $2
    RETURNING id, project_id, mcp_server_id, tool_name, title, read_only_hint, destructive_hint, idempotent_hint, open_world_hint, created_at, updated_at, deleted_at, deleted
),
removed AS (
    UPDATE mcp_server_tool_metadata
    SET deleted_at = clock_timestamp()
    WHERE mcp_server_id = $3
      AND project_id = $2
      AND deleted IS FALSE
      AND NOT EXISTS (
          SELECT 1 FROM input WHERE input.tool_name = mcp_server_tool_metadata.tool_name
      )
    RETURNING id, project_id, mcp_server_id, tool_name, title, read_only_hint, destructive_hint, idempotent_hint, open_world_hint, created_at, updated_at, deleted_at, deleted
)
SELECT
    id, project_id, mcp_server_id, tool_name, title,
    read_only_hint, destructive_hint, idempotent_hint, open_world_hint,
    created_at, updated_at, deleted_at, deleted,
    false AS was_deleted
FROM upserted
UNION ALL
SELECT
    id, project_id, mcp_server_id, tool_name, title,
    read_only_hint, destructive_hint, idempotent_hint, open_world_hint,
    created_at, updated_at, deleted_at, deleted,
    true AS was_deleted
FROM removed
ORDER BY tool_name
`

type SetMCPServerToolMetadataParams struct {
	Tools       []byte
	ProjectID   uuid.UUID
	McpServerID uuid.UUID
}

type SetMCPServerToolMetadataRow struct {
	ID              uuid.UUID
	ProjectID       uuid.UUID
	McpServerID     uuid.UUID
	ToolName        string
	Title           pgtype.Text
	ReadOnlyHint    pgtype.Bool
	DestructiveHint pgtype.Bool
	IdempotentHint  pgtype.Bool
	OpenWorldHint   pgtype.Bool
	CreatedAt       pgtype.Timestamptz
	UpdatedAt       pgtype.Timestamptz
	DeletedAt       pgtype.Timestamptz
	Deleted         bool
	WasDeleted      bool
}

// Authoritative write of an MCP server's tool metadata collection: every tool in
// @tools is upserted and every stored tool absent from @tools is soft-deleted, in a
// single statement. The two branches touch disjoint rows (partitioned by
// tool_name), so neither observes the other's writes.
//
// The conflict target is the partial unique index on (mcp_server_id, tool_name)
// WHERE deleted IS FALSE, so re-adding a soft-deleted tool inserts a fresh row
// rather than resurrecting the tombstoned one. A tool_name repeated within
// @tools trips the ON CONFLICT cardinality check (SQLSTATE 21000), aborting the
// statement rather than silently applying one of the duplicates.
// The input CTE unpacks each element with ->> rather than jsonb_to_recordset:
// sqlc's static analyzer never learns a column-definition list, so a
// recordset alias leaves every input.<column> reference unresolvable (and
// crashes sqlc outright under the managed analyzer). Selecting from
// jsonb_array_elements references only the element itself, and the per-column
// names below are ordinary select-list aliases, which sqlc does understand.
// ->> yields NULL for both an absent key and a JSON null, which is exactly the
// "hint unset" case these nullable columns encode.
func (q *Queries) SetMCPServerToolMetadata(ctx context.Context, arg SetMCPServerToolMetadataParams) ([]SetMCPServerToolMetadataRow, error) {
	rows, err := q.db.Query(ctx, setMCPServerToolMetadata, arg.Tools, arg.ProjectID, arg.McpServerID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SetMCPServerToolMetadataRow
	for rows.Next() {
		var i SetMCPServerToolMetadataRow
		if err := rows.Scan(
			&i.ID,
			&i.ProjectID,
			&i.McpServerID,
			&i.ToolName,
			&i.Title,
			&i.ReadOnlyHint,
			&i.DestructiveHint,
			&i.IdempotentHint,
			&i.OpenWorldHint,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DeletedAt,
			&i.Deleted,
			&i.WasDeleted,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

